head.script:
scwin.onpageload = function() {
	progressbar1.animate(0,100,3000,function(){});
	progressbar2.animate(0,100,3000,function(){});
	progressbar3.animate(0,30,3000,function(){});
	progressbar4.animate(0,45,3000,function(){});
};

scwin.checkVal1 = function() {
	return (document.getElementById('progressbar1_label') || document.getElementById('mf_progressbar1_label')).innerText == '100%';
};

scwin.checkVal2 = function() {
	return (document.getElementById('progressbar4_label') || document.getElementById('mf_progressbar4_label')).innerText == '45%';
};
